// Contenido del grado 10° (Estándares Básicos de Competencias en Lenguaje, MEN 2006, grupo 10-11; DBA de Lenguaje v2, MEN 2016)
import type { Grade } from './types';
const grade: Grade =
{id:'g10',n:10,title:'Literatura española y lectura crítica',desc:'Del Siglo de Oro a Lorca, leer en tres niveles y escribir textos académicos.',units:[
{id:'g10u1',title:'Literatura española',desc:'Épocas, obras y su relación con la pintura.',lessons:[
 {id:'g10u1l1',title:'Edad Media y Siglo de Oro',time:50,std:'Identifico en obras de la literatura universal el lenguaje, las características formales, las épocas y escuelas, estilos, tendencias, temáticas, géneros y autores, entre otros aspectos.',dba:'DBA 3 (10°): analiza obras literarias de distintas épocas y las relaciona con el contexto histórico y cultural en que se produjeron.',
  body:['Todo empieza en la <b>Edad Media</b> (siglos XII a XV). Se cantaba: los <b>juglares</b> la recitaban en plazas y castillos. La gran obra es el <b>Cantar de mio Cid</b> (hacia 1200), un <b>cantar de gesta</b> anónimo sobre las hazañas de Rodrigo Díaz de Vivar.',
   'Al final de la Edad Media hay dos obras clave. <b>Jorge Manrique</b> (hacia 1440-1479) escribe las <i>Coplas por la muerte de su padre</i> (hacia 1476), sobre lo breve de la vida. <b>La Celestina</b> (1499), de <b>Fernando de Rojas</b>, es un <b>puente</b> hacia el Renacimiento.',
   'En el siglo XVI llega el <b>Renacimiento</b>: se admira la cultura grecolatina, se busca la <b>armonía</b> y se idealiza la naturaleza. <b>Garcilaso de la Vega</b> (hacia 1500-1536) adapta el <b>soneto</b> italiano, de versos endecasílabos. Sus sonetos y églogas se publican en <b>1543</b>.',
   'En ese mismo siglo nace la <b>novela picaresca</b> con el <b>Lazarillo de Tormes</b> (1554), anónimo. Y los <b>místicos</b>, <b>Santa Teresa de Jesús</b> y <b>San Juan de la Cruz</b> (autor de <i>Noche oscura</i>), escriben poesía sobre la unión del alma con Dios.',
   'En el siglo XVII, el <b>Barroco</b> cambia la armonía por el <b>contraste</b> y el <b>desengaño</b>: la vida es breve y engañosa, y la juventud y la belleza terminan en polvo y en nada. <b>Góngora</b> y <b>Quevedo</b> llevan el lenguaje al extremo.',
   '<b>Lope de Vega</b> (1562-1635) renueva el teatro con obras como <i>Fuenteovejuna</i>. <b>Calderón de la Barca</b> (1600-1681) pregunta en <i>La vida es sueño</i> (1635) si lo que vivimos es real. Renacimiento y Barroco juntos forman el <b>Siglo de Oro</b>.',
   '<b>Miguel de Cervantes</b> (1547-1616) publica el <b>Quijote</b> (1605 y 1615). Es una <b>parodia de los libros de caballerías</b>: un hidalgo enloquece de tanto leerlos. Es la <b>primera novela moderna</b>: mezcla voces y narradores, juega con ficción y realidad, y sus personajes cambian y dudan.'],
  bites:[{ej:'El juglar era como un cantante de vallenato que va de pueblo en pueblo contando historias: la gente oía el Cid, no lo leía.',ojo:'"Gesta" significa hazaña: un cantar de gesta es un poema largo sobre las hazañas de un héroe.',check:{q:'¿Cómo conocía la gente el Cantar de mio Cid?',o:['Lo leía en libros impresos','Lo oía recitar a los juglares'],a:1,e:'En la Edad Media casi nadie sabía leer: los juglares lo recitaban en voz alta.'}},
   {ej:'En La Celestina, los personajes ya persiguen el placer y el dinero de este mundo, no solo el cielo: por eso anuncian una época nueva.',check:{q:'¿Por qué La Celestina es un "puente"?',o:['Porque une la Edad Media con el Renacimiento','Porque cuenta la construcción de un puente'],a:0,e:'Está al final de la Edad Media, pero sus personajes ya piensan como en el Renacimiento.'}},
   {ej:'Un soneto tiene 14 versos de 11 sílabas (endecasílabos): todo encaja, como un rompecabezas. Por eso va tan bien con la armonía renacentista.',ojo:'Renacimiento = armonía. No lo confundas con el Barroco, que viene después y busca el contraste.',check:{q:'¿Qué busca el arte del Renacimiento?',o:['La armonía y el equilibrio','El contraste y el desengaño'],a:0,e:'El contraste y el desengaño llegan después, con el Barroco.'}},
   {ej:'Lázaro es un niño pobre que sirve a un ciego y a otros amos, y sobrevive a punta de trucos: así es el pícaro.',ojo:'Picaresca viene de "pícaro": el protagonista es un antihéroe astuto, no un caballero valiente.'},
   {ej:'Góngora cierra un soneto diciendo que la belleza acabará "en tierra, en humo, en polvo, en sombra, en nada": eso es desengaño.',check:{q:'¿Qué rasgo es del Barroco?',o:['La armonía y la calma','El contraste y el desengaño','Los juglares en las plazas'],a:1,e:'El Barroco muestra que todo pasa y que la vida engaña.'}},
   {ej:'En La vida es sueño, el príncipe Segismundo despierta en un palacio y no sabe si está soñando: ¿te ha pasado al despertar de un sueño muy real?',ojo:'Siglo de Oro no es un siglo: son dos, el XVI (Renacimiento) y el XVII (Barroco).',check:{q:'¿Qué épocas forman el Siglo de Oro?',o:['Edad Media y Renacimiento','Renacimiento y Barroco'],a:1,e:'El Siglo de Oro reúne los siglos XVI y XVII.'}},
   {ej:'Cervantes nació en Alcalá de Henares (1547), quedó herido de la mano izquierda en la batalla de Lepanto (1571) y pasó cinco años cautivo en Argel (1575-1580).',ojo:'Parodia = imitar algo para burlarse de él. Cervantes imita los libros de caballerías para reírse de ellos.',check:{q:'¿De qué se burla el Quijote?',o:['De los libros de caballerías','De los juglares'],a:0,e:'Don Quijote enloquece por leer libros de caballerías: la novela se ríe de ellos.'}}],
  key:'Edad Media: juglares, el Cid y Manrique. Renacimiento: armonía, soneto y picaresca. Barroco: contraste y desengaño. Cervantes: el Quijote, parodia de los libros de caballerías y primera novela moderna.',
  co:'Cada 23 de abril, Día del Idioma, muchos colegios de Colombia leen el Quijote en voz alta; en la Biblioteca Luis Ángel Arango de Bogotá se pueden consultar ediciones antiguas y modernas de la novela.',
  act:{type:'map',kind:'timeline',prompt:'Arma la línea de tiempo: pon cada obra en su fecha.',slots:[{label:'Hacia 1200',a:'Cantar de mio Cid: épica que recitaban los juglares'},{label:'1499',a:'La Celestina: puente entre la Edad Media y el Renacimiento'},{label:'1543',a:'Sonetos de Garcilaso: armonía renacentista'},{label:'1554',a:'Lazarillo de Tormes: nace la novela picaresca'},{label:'1605',a:'Quijote (primera parte): parodia de los libros de caballerías'},{label:'1635',a:'La vida es sueño: el desengaño barroco'}],extra:['Rimas de Bécquer: intimidad romántica','Romancero gitano: vanguardia y tradición'],e:'Las dos tarjetas que sobran son de los siglos XIX y XX: no caben en esta línea de tiempo.'},
  quiz:[{q:'¿Qué obra es el gran cantar de gesta de la literatura española?',o:['La Celestina','Cantar de mio Cid','Don Quijote de la Mancha','Lazarillo de Tormes'],a:1,e:'El Cantar de mio Cid, anónimo, narra las hazañas de Rodrigo Díaz de Vivar y lo difundían los juglares.',lv:'L'},
   {q:'Un soneto termina diciendo que la juventud y la belleza acabarán "en tierra, en humo, en polvo, en sombra, en nada". ¿De qué época es?',o:['Edad Media','Renacimiento','Barroco','Romanticismo'],a:2,e:'El desengaño y la conciencia de que todo pasa son rasgos barrocos; el verso es de Luis de Góngora.',lv:'I'},
   {q:'¿Por qué se considera el Quijote la primera novela moderna?',o:['Porque es la novela más larga de su tiempo','Porque se escribió en el siglo XIX','Porque mezcla voces y estilos, parodia los libros de caballerías y muestra personajes que cambian y dudan de la realidad','Porque no tiene narrador'],a:2,e:'Cervantes juega con los narradores, los géneros y la frontera entre ficción y realidad, y sus personajes evolucionan: eso lo vuelve moderno.',lv:'C'}],
  tip:'Reparta a cada grupo una época y pídales una "portada de revista" con un autor, una obra y tres rasgos; luego ordénenlas en el tablero como línea de tiempo.'},
 {id:'g10u1l2',title:'Del Romanticismo a la Generación del 27',time:50,std:'Comparo textos de diversos autores, temas, épocas y culturas, y utilizo recursos de la teoría literaria para enriquecer su interpretación.',dba:'DBA 3 (10°): analiza obras literarias de distintas épocas y las relaciona con el contexto histórico y cultural en que se produjeron.',
  body:['El <b>Romanticismo</b> (primera mitad del siglo XIX) pone en el centro el <b>yo</b>: la emoción, la <b>libertad</b> y la naturaleza salvaje o nocturna. Lo que importa es lo que siente el poeta.',
   '<b>Espronceda</b> canta la rebeldía en la <i>Canción del pirata</i> ("mi única patria, la mar"). <b>Zorrilla</b> escribe <i>Don Juan Tenorio</i>. El sevillano <b>Bécquer</b> deja sus <i>Leyendas</i> y sus <i>Rimas</i> (1871), versos íntimos sobre el amor y la ausencia.',
   'Los movimientos viajan entre países. En Colombia, <b>Jorge Isaacs</b> publica <b>María</b> (1867): un amor imposible y un paisaje del Valle del Cauca que acompaña cada emoción. Es romántica por sus rasgos, no por el país.',
   'En la segunda mitad del siglo llega el <b>Realismo</b>: la novela observa la sociedad con detalle y sin idealizarla. <b>Galdós</b> escribe <i>Fortunata y Jacinta</i> y <b>Clarín</b>, <i>La Regenta</i>. El <b>Naturalismo</b> (Emilia Pardo Bazán) explica a los personajes por la <b>herencia</b> y el <b>medio</b>.',
   'Hacia 1900 florece el <b>Modernismo</b>, el primer movimiento que nace en Hispanoamérica y llega a España. <b>Rubén Darío</b> (1867-1916), con <i>Azul...</i> (1888), y el colombiano <b>José Asunción Silva</b>, con su <i>Nocturno</i>, buscan la <b>musicalidad</b> y la belleza del verso.',
   'En 1927, unos poetas jóvenes homenajean a Góngora: es la <b>Generación del 27</b> (Lorca, Alberti, Cernuda, Guillén, Salinas, Aleixandre). Unen la <b>vanguardia</b>, que experimenta con la forma y la metáfora, con la tradición popular del <b>romance</b> y la canción.',
   'El granadino <b>Federico García Lorca</b> publica el <i>Romancero gitano</i> (1928), una colección de romances con versos como "Verde que te quiero verde". Alberti había publicado <i>Marinero en tierra</i> (1925). Lorca fue asesinado al comenzar la Guerra Civil, en 1936.'],
  bites:[{ej:'Una canción de despecho que dice "me muero sin ti" bajo la luna tiene mucho de romántica: el yo, la emoción y la noche.',check:{q:'¿Qué pone en el centro el Romanticismo?',o:['El yo y sus emociones','La observación de la sociedad'],a:0,e:'La observación de la sociedad es del Realismo; el Romanticismo mira hacia adentro.'}},
   {ej:'Bécquer escribió: "Volverán las oscuras golondrinas / en tu balcón sus nidos a colgar". Habla de un amor que ya no volverá.',ojo:'Bécquer (poeta de las Rimas) es romántico; Galdós (novelista) es realista. No los mezcles.'},
   {ej:'En María, cuando Efraín está triste, el río y las montañas del Valle también parecen tristes.',check:{q:'¿Por qué María es romántica si se escribió en Colombia?',o:['Porque tiene los rasgos del Romanticismo','Porque Isaacs vivió en España'],a:0,e:'Un movimiento se define por sus rasgos: amor imposible, paisaje emotivo y un yo que sufre.'}},
   {ej:'En La Regenta, la esposa de un magistrado se ahoga en la rutina y los chismes de una ciudad de provincias. En Fortunata y Jacinta se ven los barrios, los negocios y el dinero de los comerciantes de Madrid.',ojo:'Naturalismo = Realismo llevado al extremo: el personaje es como es por su familia (herencia) y por el lugar donde vive (medio).',check:{q:'Una novela describe sin adornos los negocios de una familia de Madrid. ¿Qué movimiento es?',o:['Romanticismo','Realismo'],a:1,e:'Observar la sociedad con detalle y sin idealizarla es realista.'}},
   {ej:'Darío escribe: "La princesa está triste... ¿qué tendrá la princesa?". Cisnes, princesas, jardines y mundos exóticos: puro Modernismo.',ojo:'Al mismo tiempo, en España, la Generación del 98 (Unamuno, Machado) reflexiona sobre la crisis del país.',check:{q:'¿Qué busca sobre todo el Modernismo?',o:['La musicalidad y la belleza del verso','Denunciar la pobreza'],a:0,e:'El Modernismo cuida la música del verso y los ambientes bellos y exóticos.'}},
   {ej:'Es como un artista urbano que mezcla un beat electrónico con una gaita de San Jacinto: lo nuevo y lo tradicional juntos.',ojo:'Vanguardia = arte que rompe con la tradición y experimenta. La Generación del 27 la une con el romance popular.',check:{q:'¿Qué mezcla la Generación del 27?',o:['Vanguardia y tradición popular','Realismo y Naturalismo'],a:0,e:'Metáforas nuevas con formas viejas como el romance y la canción.'}},
   {ej:'"Verde que te quiero verde. / Verde viento. Verdes ramas." La repetición suena a canción popular y la imagen es de vanguardia.',check:{q:'¿Qué es el Romancero gitano?',o:['Una colección de romances de Lorca','Una novela realista'],a:0,e:'Lorca lo publicó en 1928: une el romance tradicional con metáforas nuevas.'}}],
  key:'Romanticismo: el yo y la emoción. Realismo: la sociedad observada (y el Naturalismo: herencia y medio). Modernismo: musicalidad. Generación del 27: vanguardia más tradición.',
  co:'Obras de Lorca como Bodas de sangre y La casa de Bernarda Alba se montan a menudo en grupos de teatro escolares y universitarios de Colombia, y sus romances son clásicos de los concursos de declamación.',
  act:{type:'classify',prompt:'Toca cada fragmento y ubícalo en su movimiento.',bins:['Romanticismo','Realismo','Modernismo','Generación del 27'],items:[['"Volverán las oscuras golondrinas / en tu balcón sus nidos a colgar" (Bécquer)',0],['Un pirata canta que su única patria es el mar y desprecia las leyes',0],['Una novela retrata con detalle a las familias de comerciantes de Madrid y sus negocios',1],['La esposa de un magistrado se ahoga en la rutina y los chismes de una ciudad de provincias',1],['"La princesa está triste... ¿qué tendrá la princesa?" (Rubén Darío)',2],['Versos muy musicales con cisnes, princesas y jardines exóticos',2],['"Verde que te quiero verde. / Verde viento. Verdes ramas." (Lorca)',3],['Metáforas de vanguardia mezcladas con el romance y la canción popular andaluza',3]],e:'Fíjate en el rasgo dominante: la emoción del yo, la observación social, la música del verso o la mezcla de vanguardia y tradición.'},
  quiz:[{q:'¿Quién escribió las Rimas, obra clave del Romanticismo español?',o:['Benito Pérez Galdós','Gustavo Adolfo Bécquer','Federico García Lorca','Miguel de Cervantes'],a:1,e:'Las Rimas de Bécquer se publicaron en 1871, poco después de su muerte, y son el centro de la lírica romántica española.',lv:'L'},
   {q:'Una novela describe los barrios, los oficios y el dinero de las familias de Madrid, sin idealizarlos. ¿A qué movimiento pertenece?',o:['Romanticismo','Modernismo','Generación del 27','Realismo'],a:3,e:'Observar la sociedad con detalle y sin idealizarla es el rasgo central del Realismo.',lv:'I'},
   {q:'¿Por qué María, de Jorge Isaacs, se considera romántica si se escribió en Colombia y no en España?',o:['Porque los movimientos circulan entre países: comparte el amor idealizado, la naturaleza y el sentimiento del Romanticismo','Porque Isaacs vivió siempre en Madrid','Porque se publicó en el siglo XVII','Porque es una novela realista'],a:0,e:'Un movimiento se define por sus rasgos, no por el país: María tiene el amor imposible, el paisaje emotivo del Valle del Cauca y el yo que sufre.',lv:'C'}],
  tip:'Lea en voz alta una rima de Bécquer y el "Romance sonámbulo" de Lorca; pida a los estudiantes que anoten tres diferencias de lenguaje antes de nombrar los movimientos.'},
 {id:'g10u1l3',title:'Literatura y pintura',time:50,std:'Comprendo en los textos que leo las dimensiones éticas, estéticas, filosóficas, entre otras, que se evidencian en ellos.',dba:'DBA 4 (10°): formula puntos de encuentro entre la literatura y las artes plásticas y visuales.',
  body:['Cada época tiene una forma de sentir que se ve en palabras e imágenes. En el Toledo del siglo XVI, <b>El Greco</b> pinta figuras alargadas que parecen subir al cielo: la misma <b>espiritualidad</b> de los místicos Santa Teresa y San Juan de la Cruz.',
   'En el <b>Barroco</b>, la pintura juega con el <b>claroscuro</b>: el contraste fuerte de luz y sombra. Es lo mismo que hace la poesía barroca cuando juega con los opuestos.',
   '<b>Velázquez</b> (1599-1660), pintor de la corte de Felipe IV, pinta <i>Las meninas</i> (1656). Un espejo y un pintor que nos mira hacen dudar de quién observa a quién. Calderón duda igual en <i>La vida es sueño</i>: ¿realidad o apariencia?',
   '<b>Goya</b> (1746-1828) se adelanta al <b>Romanticismo</b>. En <i>El sueño de la razón produce monstruos</i> (1799), de la serie <i>Los caprichos</i>, un hombre dormido está rodeado de búhos y murciélagos: lo <b>nocturno</b> y lo <b>irracional</b> que luego explorarán los románticos.',
   'En el siglo XX, las <b>vanguardias</b> rompen la imagen. <b>Picasso</b> (1881-1973) pinta el <i>Guernica</i> (1937) sobre el bombardeo de esa villa en la Guerra Civil española, con figuras fragmentadas que gritan de dolor.',
   'El <b>surrealismo</b> busca los sueños y lo irracional. <b>Salvador Dalí</b> fue amigo de Lorca en la Residencia de Estudiantes de Madrid. Lorca llena <i>Poeta en Nueva York</i> (1929-1930) de imágenes de sueño, rotas en fragmentos, que expresan <b>angustia</b>.',
   'Para <b>comparar</b> un poema y una pintura, mira cuatro cosas: el tema, los recursos, la visión del mundo y el contexto. Y sustenta cada parecido con un <b>rasgo concreto</b> de cada obra, no con un "se parecen".'],
  bites:[{ej:'Es como cuando una canción y su video transmiten la misma emoción: en el siglo XVI, cuadro y poema miraban hacia Dios.',check:{q:'¿Qué comparten El Greco y los místicos?',o:['La espiritualidad','El humor y la parodia'],a:0,e:'Las figuras que suben al cielo expresan lo mismo que la poesía sobre el alma y Dios.'}},
   {ej:'Piensa en una foto con una vela en un cuarto oscuro: la cara iluminada y todo lo demás en sombra. Eso es claroscuro.',ojo:'Barroco = contraste, en la pintura (luz y sombra) y en la poesía (vida y muerte, belleza y polvo).'},
   {ej:'Velázquez nació en 1599, cuando Cervantes aún vivía: los dos son del Siglo de Oro.',ojo:'El colombiano Fernando Botero pintó sus propias versiones de retratos de Velázquez: un diálogo entre épocas.',check:{q:'¿Qué idea comparten Las meninas y La vida es sueño?',o:['La duda entre realidad y apariencia','La crítica a la guerra'],a:0,e:'En los dos no se sabe bien qué es real y qué es ilusión.'}},
   {ej:'¿Has visto una película de terror que pasa en sueños? Goya ya pintaba esos monstruos de la noche en 1799.',ojo:'Goya murió en 1828 y Bécquer nació en 1836: comparten sensibilidad, pero no fueron contemporáneos.',check:{q:'¿Con qué movimiento conecta el grabado de Goya?',o:['Con el Romanticismo','Con el Renacimiento'],a:0,e:'Lo nocturno y lo irracional serán temas románticos.'}},
   {ej:'En el Guernica hay una madre con su hijo en brazos, un caballo herido y un toro, todos en pedazos y en blanco y negro.',check:{q:'¿Cómo son las figuras del Guernica?',o:['Fragmentadas, rotas en pedazos','Armoniosas y tranquilas'],a:0,e:'Las vanguardias rompen la imagen para expresar el dolor de la guerra.'}},
   {ej:'Un reloj que se derrite, como en un cuadro de Dalí, es una imagen de sueño: no tiene lógica, pero expresa algo.',ojo:'Surrealismo = sueños e imágenes irracionales. Lo usan tanto Dalí (pintura) como Lorca (poesía).'},
   {ej:'"Guernica y Poeta en Nueva York se parecen porque los dos usan imágenes fragmentadas para expresar angustia, en los mismos años": esa es una comparación con rasgo concreto.',check:{q:'¿Cuál es una comparación sólida?',o:['"Los dos son famosos"','"Los dos usan imágenes rotas para expresar angustia"'],a:1,e:'Una buena comparación señala un rasgo concreto que está en las dos obras.'}}],
  key:'El Greco y los místicos: espiritualidad. Velázquez y Calderón: apariencia. Goya: lo nocturno. Picasso, Dalí y Lorca: fragmentos y sueños. Compara con rasgos concretos.',
  co:'Fernando Botero pintó versiones propias de retratos de Velázquez, como el de la infanta Margarita; en el Museo Botero de Bogotá, de entrada libre, se puede ver cómo un artista colombiano dialoga con la tradición española.',
  act:{type:'match',prompt:'Une cada pintura con el texto o la idea que comparte su forma de sentir.',pairs:[['El Greco: figuras alargadas que suben al cielo','Los místicos: el alma que busca a Dios'],['Claroscuro: luz contra sombra','Poesía barroca: juego de opuestos'],['Las meninas (Velázquez, 1656)','La vida es sueño (Calderón, 1635)'],['El sueño de la razón (Goya, 1799)','Romanticismo: lo nocturno y lo irracional'],['Guernica (Picasso, 1937)','Poeta en Nueva York (Lorca, 1929-1930)'],['Retratos de Velázquez','Versiones de Fernando Botero']],e:'Una comparación sólida une obras por un rasgo concreto que comparten, no solo porque "se parecen".'},
  quiz:[{q:'¿Qué pintor español hizo Las meninas?',o:['Francisco de Goya','Pablo Picasso','Diego Velázquez','Salvador Dalí'],a:2,e:'Velázquez, pintor de la corte de Felipe IV, la pintó en 1656.',lv:'L'},
   {q:'En "El sueño de la razón produce monstruos", de Goya, un hombre dormido está rodeado de búhos y murciélagos. ¿Con qué movimiento literario posterior conecta?',o:['Con el Renacimiento, por su armonía','Con el Romanticismo, por lo nocturno y lo irracional','Con el Realismo, por su observación social','Con la Edad Media, por los juglares'],a:1,e:'La noche, los sueños y lo irracional son temas que los románticos desarrollarán después.',lv:'I'},
   {q:'¿Qué hace válida la comparación entre un poema y una pintura?',o:['Que tengan el mismo tamaño','Que los dos sean famosos','Que compartan época, tema o recursos, y que la comparación se sustente en rasgos concretos de cada obra','Que el autor sea la misma persona'],a:2,e:'Comparar exige evidencia: señalar en cada obra el rasgo que las acerca o las separa.',lv:'C'}],
  tip:'Proyecte Las meninas en silencio durante un minuto y pida que escriban tres preguntas sobre quién mira a quién; luego lean la décima "¿Qué es la vida? Un frenesí..." de Calderón.'}
]},
{id:'g10u2',title:'Lectura crítica',desc:'Tres niveles de lectura, textos discontinuos y la postura del autor.',lessons:[
 {id:'g10u2l1',title:'Los tres niveles de lectura',time:50,std:'Comprendo e interpreto textos con actitud crítica y capacidad argumentativa.',dba:'DBA 6 (10°): comprende el sentido global de los textos que lee, la intención de quien los produce y las características del contexto en que se producen.',
  body:['El <b>nivel literal</b> es lo que el texto dice de forma explícita: datos, fechas, nombres y hechos. La respuesta está escrita y se puede señalar con el dedo: esa es la <b>evidencia</b>.',
   'El <b>nivel inferencial</b> es lo que el texto da a entender sin decirlo. Se deduce uniendo <b>pistas</b>. Si un personaje mira el reloj a cada rato y golpea el piso con el pie, se infiere que está impaciente.',
   'Se puede inferir una causa, una intención, el sentido de una palabra por el contexto, la <b>relación entre partes</b> (un párrafo que explica, contradice o ejemplifica a otro) o la <b>idea global</b>. Una buena inferencia siempre se apoya en algo del texto.',
   'El <b>nivel crítico</b> evalúa el texto. Pregúntate: ¿los argumentos son sólidos?, ¿las fuentes son confiables?, ¿qué postura e <b>intereses</b> tiene quien escribe?, ¿los datos bastan para sostener la tesis?, ¿estoy de acuerdo y por qué?',
   'Desconfía de las <b>generalizaciones</b> (<i>todos, nadie, siempre</i>) y de las afirmaciones sin fuente ni cifras. No se aceptan porque estén escritas: se <b>verifican</b>.',
   'La prueba <b>Saber 11</b> de Lectura Crítica mide estas tres miradas: entender lo que dice cada parte, comprender el sentido global y reflexionar para evaluar el contenido.'],
  bites:[{ej:'"El TransMiCable se inauguró en diciembre de 2018." ¿Cuándo se inauguró? La respuesta está escrita tal cual.',check:{q:'Una pregunta literal se responde…',o:['con un dato que está escrito en el texto','con tu opinión'],a:0,e:'En el nivel literal la respuesta se puede señalar en el texto.'}},
   {ej:'"Camila leyó el mensaje, suspiró y no quiso cenar." No dice que está triste, pero las pistas lo dejan ver.',ojo:'Inferir no es inventar: si no puedes señalar la pista en el texto, no es una inferencia.',check:{q:'"Julián se secaba las manos y no probó el almuerzo antes de exponer." ¿Qué se infiere?',o:['Que estaba nervioso','Que no le gusta el almuerzo del colegio'],a:0,e:'Las manos sudadas y la falta de apetito son pistas de nervios.'}},
   {ej:'"El paisaje estaba trasnochado": por el contexto, "trasnochado" aquí significa viejo o gastado, no que alguien durmió poco.',ojo:'Preguntas como "¿cuál es la idea global?" o "¿qué relación hay entre dos párrafos?" también son inferenciales.'},
   {ej:'Un concejal escribe que el TransMiCable "es la mejor obra de la historia de Bogotá". ¿Con qué datos lo prueba? ¿Qué interés tiene?',check:{q:'¿Cuál es una pregunta crítica?',o:['¿Es confiable la fuente que cita el autor?','¿En qué año pasó?'],a:0,e:'Evaluar la fuente es propio del nivel crítico; el año es un dato literal.'}},
   {ej:'"Todos los jóvenes prefieren el reguetón", sin datos: es una generalización que no se puede sostener.',ojo:'Palabras alarma: todos, nadie, siempre, nunca. Cuando las veas, busca la prueba.',check:{q:'Un texto dice "nadie lee en Colombia" sin cifras. ¿Qué haces?',o:['Lo acepto porque está escrito','Lo pongo en duda y busco datos'],a:1,e:'Una generalización sin fuente se verifica antes de creerla.'}},
   {ej:'En un simulacro Saber, una pregunta pide un dato (literal), otra la intención del autor (inferencial) y otra si el argumento es sólido (crítica).',check:{q:'¿Cuántas miradas de lectura mide la prueba Saber 11?',o:['Dos','Tres'],a:1,e:'Lo local, el sentido global y la reflexión que evalúa: los tres niveles.'}}],
  key:'Literal: lo que dice. Inferencial: lo que da a entender. Crítico: lo que se puede juzgar. Siempre con evidencia del texto.',
  co:'El TransMiCable de Ciudad Bolívar, inaugurado en diciembre de 2018, redujo de cerca de una hora a unos trece minutos el viaje de muchos vecinos: un buen tema para leer noticias en los tres niveles.',
  act:{type:'mark',prompt:'Elige un nivel y toca su evidencia: datos literales, pistas para inferir cómo le va a doña Marleny y afirmaciones que hay que poner en duda.',cats:[{n:'Dato literal',c:'#1F5FA8'},{n:'Pista para inferir',c:'#B06A10'},{n:'Afirmación para evaluar',c:'#C0453A'}],text:'El TransMiCable de Ciudad Bolívar se inauguró [[en diciembre de 2018|0]]. Antes, muchos vecinos de los barrios altos gastaban cerca de una hora para bajar al portal; hoy el viaje dura [[unos trece minutos|0]]. Doña Marleny, que vende arepas en el portal, cuenta que [[ya no pierde a sus primeros clientes|1]] y que [[este año compró una segunda plancha|1]]. Un concejal escribió en redes que [[es la mejor obra de la historia de Bogotá|2]], y una publicación sin firma asegura que [[todos los barrios tendrán cable en dos años|2]].',e:'Los datos literales se leen tal cual; las pistas se unen para deducir que a doña Marleny le va mejor; las dos últimas afirmaciones no traen fuentes ni cifras que las respalden.'},
  quiz:[{q:'"La Biblioteca Virgilio Barco, diseñada por Rogelio Salmona, abrió en 2001." Según el texto, ¿en qué año abrió?',o:['1991','2001','2011','El texto no lo dice'],a:1,e:'Es un dato explícito: la respuesta está escrita en el texto.',lv:'L'},
   {q:'"Después de leer el mensaje, Camila guardó el celular, suspiró y no quiso cenar." ¿Qué se puede inferir?',o:['Que ya había comido','Que el celular se dañó','Que el mensaje le trajo una mala noticia','Que la cena estaba fría'],a:2,e:'El suspiro y la falta de apetito justo después del mensaje son pistas de que algo la afectó.',lv:'I'},
   {q:'Un texto afirma: "Todos los jóvenes de Bogotá prefieren el reguetón", sin dar datos. ¿Qué hace un lector crítico?',o:['Lo acepta porque está escrito','Cuestiona la generalización y busca evidencia que la respalde o la refute','Lo memoriza para el examen','Deja de leer el texto'],a:1,e:'"Todos" es una generalización: sin datos no se puede sostener.',lv:'C'}],
  tip:'Con una noticia del día, pida que cada grupo escriba una pregunta de cada nivel y la intercambie con otro grupo, que debe responder citando la evidencia.'},
 {id:'g10u2l2',title:'Textos discontinuos',time:50,std:'Diseño un esquema de interpretación, teniendo en cuenta el tipo de texto, tema, interlocutor e intención comunicativa.',dba:'DBA 2 (10°): explica cómo se articulan los códigos verbales y no verbales en infografías, caricaturas y otras manifestaciones. DBA 6 (10°): comprende el sentido global de los textos que lee.',
  body:['Un texto <b>continuo</b> se lee de corrido, en párrafos, como un cuento o una carta. Un texto <b>discontinuo</b> organiza la información en tablas, gráficas, infografías, mapas, horarios, formularios o <b>caricaturas</b>, y se lee saltando entre sus partes.',
   'Para leerlo, mira primero el <b>título</b>, la <b>fuente</b> y la <b>fecha</b>. Luego, los <b>ejes</b>, las unidades y las <b>convenciones</b> (la leyenda que explica colores y símbolos). Localizar un dato es lectura literal; comparar barras o ver una <b>tendencia</b> ya es inferir.',
   'Un <b>porcentaje</b> es una parte de cada cien. El 25 % es <b>una cuarta parte</b> ("1 de cada 4") y el 50 % es la <b>mitad</b>. Por eso, un 45 % todavía no alcanza la mitad.',
   'Un <b>aumento</b> en porcentaje se calcula sobre el valor inicial. Si los inscritos pasan de 200 a 250, subieron 50, y 50 es el 25 % de 200. Ojo: si algo pasa del 10 % al 15 %, subió 5 <b>puntos</b>.',
   'No concluyas más de lo que muestran los datos. Una gráfica de dos meses no habla de todo el año. Una encuesta a un solo curso no es una <b>muestra</b> que represente a todos los jóvenes del país.',
   'La <b>caricatura</b> une dibujo y palabra para opinar con humor, <b>exageración</b> e <b>ironía</b>. Solo se entiende si conoces el contexto: la noticia de la que habla.',
   'En el nivel crítico te preguntas qué defiende el autor y si puedes verificar la fuente y la fecha. Un eje que no empieza en cero exagera las diferencias: con datos reales, la gráfica es <b>engañosa</b>. Si los datos son inventados, es <b>falsa</b>.'],
  bites:[{ej:'La tabla de posiciones de la Liga colombiana es un texto discontinuo: nadie la lee de corrido, buscas a tu equipo y saltas a sus puntos.',check:{q:'¿Cuál es un texto discontinuo?',o:['Un cuento','El horario de un bus'],a:1,e:'El horario organiza datos en filas y columnas: se lee saltando.'}},
   {ej:'En un mapa con convenciones, azul puede ser "ríos" y verde "parques": sin la leyenda no sabrías qué significa cada color.',ojo:'Si los inscritos pasan de 200 a 250 y luego a 300, la tendencia es subir 50 cada año: eso ya es inferir.',check:{q:'¿Qué conviene mirar primero en una infografía?',o:['El título, la fuente y la fecha','Los colores más bonitos'],a:0,e:'La fuente y la fecha dicen de dónde salen los datos y si están al día.'}},
   {ej:'Si 1 de cada 4 estudiantes lee a diario, es el 25 %: una cuarta parte del colegio.',ojo:'45 % es mucho, pero no es "la mayoría absoluta": para eso hay que pasar del 50 %.',check:{q:'¿Un 45 % es más de la mitad?',o:['Sí','No'],a:1,e:'La mitad es el 50 %; 45 % se queda corto.'}},
   {ej:'De 250 a 300 inscritos: subieron 50, que es el 20 % de 250. El porcentaje cambia porque el valor inicial es distinto.',ojo:'Error típico: decir que de 200 a 250 "subió un 50 %". Subió 50 personas, que es el 25 %.'},
   {ej:'Una gráfica muestra lluvias de abril (120 mm) y julio (40 mm). Puedes decir que en abril llovió el triple, pero no que julio fue el mes más seco del año.',check:{q:'Encuestaron a 40 estudiantes de un curso. ¿Representan a todos los jóvenes del país?',o:['Sí, porque son jóvenes','No, la muestra es muy pequeña y particular'],a:1,e:'Para generalizar se necesita una muestra grande y variada.'}},
   {ej:'Caricaturistas como Matador o Vladdo dibujan a un político con una nariz enorme o cortando la cinta de un puente sin terminar para criticarlo.',ojo:'Sin conocer la noticia de la semana, la caricatura no se entiende: el contexto es la clave.'},
   {ej:'Ventas de 100 y 110 con un eje que empieza en 95: la segunda barra parece el triple de alta, pero solo subió un 10 %.',ojo:'Engañosa = dato real mal presentado. Falsa = dato inventado. Confiable = dato con fuente y fecha, bien presentado.',check:{q:'Una gráfica con datos reales pero con el eje recortado es…',o:['engañosa','falsa'],a:0,e:'Los datos existen, pero la imagen exagera: engaña a la vista.'}}],
  key:'Título, fuente, fecha, ejes y convenciones. Localiza el dato, lee bien los porcentajes, compara sin ir más allá de los datos y pregúntate si la imagen dice la verdad.',
  co:'Matador, en El Tiempo, y Vladdo, creador de Aleida, resumen en una sola viñeta un debate nacional: para entenderlos hay que conocer la noticia de la semana.',
  act:{type:'fix',prompt:'Toca las conclusiones mal sacadas de la encuesta y corrígelas.',text:'ENCUESTA A 600 ESTUDIANTES (marzo de 2026): a pie, 45 %; bus, 30 %; bicicleta, 15 %; carro, 10 %. CONCLUSIONES: El medio más usado es {{caminar|el bus}}. Ese 45 % es {{menos|más}} de la mitad del colegio. La bicicleta {{supera|no alcanza}} al carro. El club de ciclismo pasó de 200 a 250 inscritos: subió un {{25|50}} %. Como la encuesta se hizo en un solo colegio, {{no|sí}} representa a todos los jóvenes del país.',e:'Lee los números con cuidado: el 45 % no es la mitad, un aumento se calcula sobre el valor inicial y un solo colegio no representa a todo el país.'},
  quiz:[{q:'Una tabla dice: "Bicicleta: 15 %. Carro o moto: 10 %". ¿Qué porcentaje llega en bicicleta?',o:['10 %','15 %','25 %','45 %'],a:1,e:'Es un dato literal: se lee directamente en la tabla.',lv:'L'},
   {q:'Una gráfica muestra el consumo de agua de un barrio: enero, 100 m³; febrero, 90 m³; marzo, 80 m³. ¿Qué tendencia se puede inferir?',o:['El consumo aumenta cada mes','El consumo baja 10 m³ cada mes','El consumo no cambia','En abril será cero'],a:1,e:'Comparar los datos permite inferir una tendencia; predecir que en abril será cero va más allá de la evidencia.',lv:'I'},
   {q:'En una gráfica de barras, las ventas pasan de 100 a 110, pero el eje empieza en 95 y la segunda barra parece el triple de alta. ¿Qué concluye un lector crítico?',o:['Las ventas se triplicaron','La gráfica está bien porque tiene números','El eje recortado exagera visualmente un aumento del 10 %','Las ventas bajaron'],a:2,e:'Un eje que no empieza en cero agranda las diferencias: la imagen dice más de lo que dicen los datos.',lv:'C'}],
  tip:'Lleve una caricatura de la semana y una infografía de un periódico; pida que subrayen primero la fuente y la fecha y luego escriban en una línea qué opina el caricaturista.'},
 {id:'g10u2l3',title:'Intención y postura del autor',time:50,std:'Elaboro hipótesis de interpretación atendiendo a la intención comunicativa y al sentido global del texto que leo.',dba:'DBA 1 (10°): asume una posición crítica frente a los discursos de los medios de comunicación y analiza su influencia en la sociedad. DBA 6 (10°): comprende la intención de quien produce el texto.',
  body:['Todo texto tiene una <b>intención comunicativa</b>: informar, persuadir, criticar, denunciar o entretener. Una noticia busca informar. Una <b>columna de opinión</b> o un editorial buscan convencerte de una <b>tesis</b>.',
   'La <b>postura</b> del autor se nota en el lenguaje. Mira las <b>palabras valorativas</b> (<i>vergonzoso, admirable, lamentablemente</i>) y las expresiones de <b>opinión o certeza</b> (<i>considero, a mi juicio, sin duda</i>).',
   'También la revelan las <b>preguntas retóricas</b>, que no esperan respuesta, y la <b>ironía</b>, que dice lo contrario de lo que piensa. Y cuenta qué datos elige mostrar el autor y cuáles calla.',
   'Si lees dos columnas opuestas, busca en cada una la tesis, los argumentos y las pruebas. Un <b>argumento</b> sólido se apoya en datos con fuente, ejemplos comprobables o un <b>experto en ese tema</b>. Una <b>falacia</b> solo parece válida.',
   'Unas falacias atacan al otro. <b>Ad hominem</b>: ataca a la persona, no sus ideas. <b>Hombre de paja</b>: deforma la idea del otro para atacarla. <b>Falsa autoridad</b>: cree a un famoso en un tema ajeno. <b>Apelación a la mayoría</b>: "muchos lo creen, entonces es cierto".',
   'Otras fallan al razonar. <b>Generalización apresurada</b>: concluye algo general de un solo caso. <b>Falso dilema</b>: da solo dos opciones cuando hay más. <b>Pendiente resbaladiza</b>: supone, sin pruebas, consecuencias cada vez peores. <b>Falsa causa</b>: cree que lo que pasó después fue causado por lo anterior.'],
  bites:[{ej:'"Se aplazó la ciclorruta de la avenida" informa. "La ciclorruta debe construirse ya" es una tesis: quiere convencerte.',check:{q:'¿Qué busca una columna de opinión?',o:['Convencer al lector de una tesis','Solo dar la fecha de un hecho'],a:0,e:'La noticia informa; la columna defiende una postura.'}},
   {ej:'"Lamentablemente, la obra se aplazó otra vez": "lamentablemente" muestra que al autor le parece mal.',ojo:'Frases como "el 12 de marzo" o "según el DANE" son datos, no opiniones.',check:{q:'¿Cuál es una marca de opinión?',o:['Asistieron 200 personas','A mi juicio'],a:1,e:'"A mi juicio" anuncia que viene la opinión del autor.'}},
   {ej:'"Qué eficiencia la del contratista: solo lleva seis años de retraso." Dice "eficiencia" para criticar: es ironía.',check:{q:'"¿Cuántos accidentes más necesitamos para actuar?" es…',o:['una pregunta retórica','una pregunta literal'],a:0,e:'No espera respuesta: sirve para reforzar la postura del autor.'}},
   {ej:'"El parque debe conservarse: lo usan cientos de familias cada semana, según la junta de acción comunal." Tesis más dato con fuente: argumento sólido.',ojo:'Un experto sirve solo en su tema: un médico sobre salud, sí; un futbolista sobre salud, no.'},
   {ej:'"¿Qué va a saber él, si nunca terminó el colegio?" (ad hominem). "Quienes piden ciclorrutas quieren prohibir los carros" (hombre de paja).',check:{q:'"No le hagas caso a esa columnista, es muy joven." ¿Qué falacia es?',o:['Ad hominem','Falsa causa'],a:0,e:'Ataca a la persona (su edad), no sus argumentos.'}},
   {ej:'"O construimos la autopista o la ciudad colapsa" (falso dilema). "La biblioteca abrió el lunes y el martes bajaron los robos: la biblioteca acabó con la inseguridad" (falsa causa).',ojo:'Truco: generalización = un caso para todos; dilema = solo dos caminos; pendiente = efecto dominó; falsa causa = "después" no es "por culpa de".',check:{q:'"A mi vecino le robó un ciclista: todos los ciclistas son ladrones." ¿Qué falacia es?',o:['Generalización apresurada','Apelación a la mayoría'],a:0,e:'Saca una conclusión sobre todos a partir de un solo caso.'}}],
  key:'Busca la tesis y las marcas de opinión: palabras valorativas, certezas, preguntas retóricas e ironía. Luego pesa argumentos y nombra las falacias.',
  co:'Cuando se discute una obra de ciudad, como una ciclorruta o la peatonalización de una calle, los periódicos publican columnas a favor y en contra: leerlas juntas es un ejercicio de lectura crítica.',
  act:{type:'comic',prompt:'Completa lo que dicen Valentina y Andrés mientras leen una columna.',panels:[{who:'Valentina',face:'🧐',say:'"Lamentablemente, aplazaron la ciclorruta." Esa palabra es {{valorativa|un dato|una fuente}}: muestra que al autor le parece mal.'},{who:'Andrés',face:'🤔',say:'Y cuando pregunta "¿Cuántos accidentes más necesitamos?", no espera respuesta: es una pregunta {{retórica|literal}}.'},{who:'Valentina',face:'😏',say:'"Qué gran planeación, anunciar obras que nunca empiezan." Dice lo contrario de lo que piensa: es {{ironía|un dato|una tesis}}.'},{who:'Andrés',face:'😒',say:'Igual yo no le creo: ese columnista ni terminó el colegio.'},{who:'Valentina',face:'🙅‍♀️',say:'Eso es un {{ad hominem|argumento sólido|falso dilema}}: atacas a la persona. Mejor mira si trae {{datos con fuente|muchos adjetivos}}.'},{who:'Andrés',face:'😅',say:'Tienes razón. Y si digo "o hacen la ciclorruta o todos morimos", caigo en un {{falso dilema|hombre de paja}}.'}],e:'La postura se lee en las marcas del lenguaje, y un lector crítico separa los argumentos de las falacias.'},
  quiz:[{q:'En "Lamentablemente, la obra se aplazó otra vez", ¿qué palabra revela con más claridad la postura del autor?',o:['la obra','se aplazó','Lamentablemente','vez'],a:2,e:'"Lamentablemente" es un adverbio valorativo: muestra que al autor le parece mal el aplazamiento.',lv:'L'},
   {q:'Un columnista escribe: "Qué eficiencia la del contratista: solo lleva seis años de retraso". ¿Cuál es su intención?',o:['Criticar el retraso con ironía','Elogiar al contratista','Informar la fecha de entrega','Pedir más plazo para la obra'],a:0,e:'Dice "eficiencia" para señalar lo contrario: es ironía al servicio de la crítica.',lv:'I'},
   {q:'Dos columnas opinan sobre el mismo parque: una lo defiende con cifras de uso y la otra ataca la vida personal del alcalde que lo propuso. ¿Cuál argumenta mejor?',o:['La segunda, porque es más emotiva','Las dos por igual','Ninguna, porque las columnas no argumentan','La primera, porque se apoya en datos; la segunda comete una falacia ad hominem'],a:3,e:'Atacar a la persona no dice nada sobre el parque: es una falacia. Los datos de uso sí son un argumento.',lv:'C'}],
  tip:'Imprima dos columnas opuestas sobre un tema de ciudad y pida a cada pareja que resalte en colores distintos las marcas de opinión; luego debatan cuál sustenta mejor su tesis.'}
]},
{id:'g10u3',title:'Producción académica',desc:'Reseña crítica, exposición oral y corrección.',lessons:[
 {id:'g10u3l1',title:'La reseña crítica',time:50,std:'Produzco textos argumentativos que evidencian mi conocimiento de la lengua y el control sobre su uso en contextos comunicativos orales y escritos.',dba:'DBA 8 (10°): produce textos académicos con coherencia y cohesión, a partir de un plan y de procesos de revisión y reescritura.',
  body:['La <b>reseña crítica</b> es un texto breve que presenta una obra (un libro, una película, un disco o una exposición) y la <b>valora</b> con argumentos. Sale en revistas, blogs y suplementos culturales, y ayuda al lector a decidir si la lee o la ve.',
   'Tiene cuatro partes. La primera es la <b>ficha técnica</b>: título, autor o director, año, editorial o productora. La segunda es el <b>resumen</b>: cuenta de qué trata la obra sin revelar el final (sin <i>spoilers</i>).',
   'La tercera parte es la <b>valoración</b>, que juzga la obra con criterios. La cuarta es la <b>recomendación</b>, que dice para quién es la obra y por qué.',
   'El resumen es <b>objetivo</b>: se escribe en tercera persona, en presente y sin juicios. Cuenta, no opina.',
   'La valoración es <b>argumentada</b>. No basta con "me gustó": elige <b>criterios</b> (los personajes, el lenguaje, la estructura, la fotografía) y da <b>ejemplos</b> de la obra que sostengan cada juicio.',
   'Para escribirla, sigue el proceso: lee o ve la obra con atención y toma notas. Luego completa la ficha, escribe el resumen sin contar el final, redacta la valoración con criterios y ejemplos, y cierra con la recomendación.',
   'Por último, <b>revisa y corrige</b>. Separa bien lo que resumes de lo que opinas, y cuida las tildes, la concordancia y la puntuación.'],
  bites:[{ej:'Antes de ir a cine, muchos leen una reseña de la película en internet para saber si vale la pena.',check:{q:'¿Qué hace una reseña crítica?',o:['Presenta una obra y la valora con argumentos','Cuenta la obra completa, con el final'],a:0,e:'La reseña ayuda a decidir: presenta y juzga, sin arruinar la sorpresa.'}},
   {ej:'Ficha: "El olvido que seremos, Fernando Trueba, 2020". Resumen: "Un médico de Medellín defiende los derechos humanos mientras…".',ojo:'Spoiler = contar el final. En el resumen está prohibido.'},
   {ej:'Valoración: "La fotografía es el mayor acierto de la película". Recomendación: "Para quien quiera entender la violencia de los años ochenta".',check:{q:'"Se la recomiendo a quien le guste el Romanticismo." ¿Qué parte es?',o:['La recomendación','La ficha técnica'],a:0,e:'Dice para quién es la obra y por qué.'}},
   {ej:'"Efraín regresa a la hacienda de su familia y se enamora de su prima María." Tercera persona, presente y sin opinar.',check:{q:'¿Cuál frase sirve para un resumen?',o:['La historia transcurre durante un verano en Cartagena','El final se siente apresurado'],a:0,e:'La segunda juzga la obra: es valoración, no resumen.'}},
   {ej:'Criterio: la actuación. Ejemplo: "En la escena del hospital, el protagonista pasa del miedo a la rabia sin decir una palabra".',ojo:'"Me encantó, es lo mejor" es una valoración débil: no dice por qué. Siempre criterio + ejemplo.',check:{q:'¿Qué necesita una buena valoración?',o:['Criterios y ejemplos de la obra','Muchos signos de admiración'],a:0,e:'Los criterios dicen qué juzgas y los ejemplos lo prueban.'}},
   {ej:'Si reseñas un libro de la FILBo, toma notas mientras lees: una frase buena, un personaje, una escena clave.',ojo:'Orden del proceso: notas → ficha → resumen → valoración → recomendación → revisión.'},
   {ej:'"El libro reúne doce cuentos. Me parece que son geniales" mezcla resumen y opinión en la misma parte: sepáralos.',check:{q:'¿Qué revisas al final?',o:['Que no mezcles resumen y opinión, y la ortografía','Que la reseña sea lo más larga posible'],a:0,e:'La revisión cuida la estructura y la corrección del texto.'}}],
  key:'Ficha, resumen sin spoilers, valoración con criterios y ejemplos, y recomendación. Luego, revisa y corrige.',
  co:'Cada año la FILBo, la Feria Internacional del Libro de Bogotá, presenta decenas de novedades; reseñar un libro de la feria o una película colombiana como El olvido que seremos (2020) es un buen ejercicio.',
  act:{type:'write',prompt:'Escribe la reseña crítica de un libro o una película colombiana que conozcas bien. Sigue los pasos: ficha, resumen, valoración y revisión.',purpose:{q:'¿Cuál es el propósito de tu reseña?',o:['Presentar y valorar la obra con argumentos para que otros decidan si la leen o la ven','Contar la obra completa, incluido el final','Hacer publicidad para que la compren']},plan:[{q:'Ficha técnica: título, autor o director, año',ph:'El olvido que seremos, Fernando Trueba, 2020'},{q:'Resumen en una frase (sin contar el final)',ph:'Un médico de Medellín defiende los derechos humanos mientras…'},{q:'Criterio 1 que vas a valorar y un ejemplo',ph:'La fotografía: el contraste entre color y blanco y negro'},{q:'Criterio 2 que vas a valorar y un ejemplo',ph:'La actuación del protagonista en la escena del hospital'},{q:'¿A quién se la recomiendas y por qué?',ph:'A quien quiera entender la violencia de los años ochenta'}],min:180,checklist:['La ficha técnica tiene título, autor o director y año.','El resumen está en tercera persona y no revela el final.','La valoración usa al menos dos criterios con ejemplos de la obra.','Distingo con claridad lo que resumo de lo que opino.','Cierro con una recomendación dirigida a un tipo de lector o espectador.','Revisé tildes, concordancia y puntuación.'],model:'<b>María</b>, Jorge Isaacs, 1867. Novela. Efraín regresa a la hacienda de su familia en el Valle del Cauca y se enamora de su prima María, pero un viaje de estudios a Londres amenaza ese amor. La novela vale sobre todo por sus descripciones del paisaje: el río, las montañas y los cultivos acompañan cada emoción de los personajes. Su lenguaje es delicado, aunque hoy su ritmo puede parecer lento y sus personajes femeninos, poco activos. Se la recomiendo a quien quiera entender el Romanticismo hispanoamericano y el Valle del Cauca del siglo XIX.'},
  quiz:[{q:'¿Qué parte de la reseña incluye título, autor, año y editorial?',o:['La ficha técnica','La valoración','La recomendación','El resumen'],a:0,e:'La ficha técnica identifica la obra antes de hablar de ella.',lv:'L'},
   {q:'"La novela atrapa desde la primera página, aunque el final se siente apresurado." ¿Qué tipo de enunciado es?',o:['Resumen, porque cuenta la historia','Ficha técnica','Valoración, porque juzga la obra','Cita del autor'],a:2,e:'"Atrapa" y "se siente apresurado" son juicios sobre la calidad de la obra.',lv:'I'},
   {q:'¿Por qué una reseña que solo dice "me encantó, es lo mejor" es una valoración débil?',o:['Porque es muy corta','Porque no da criterios ni ejemplos que sustenten el juicio','Porque toda reseña debe ser negativa','Porque no cuenta el final'],a:1,e:'Sin criterios y sin ejemplos, el lector no sabe por qué debería confiar en ese juicio.',lv:'C'}],
  tip:'Lea dos reseñas publicadas de la misma película, una positiva y una negativa, y pida que subrayen los criterios que usa cada una.'},
 {id:'g10u3l2',title:'La ponencia y la relatoría',time:50,std:'Caracterizo y utilizo estrategias descriptivas y explicativas para argumentar mis ideas, valorando y respetando las normas básicas de la comunicación.',dba:'DBA 5 (10°): expone oralmente sus ideas en escenarios académicos con un plan y apoyos visuales. DBA 7 (10°): participa en discusiones académicas y recoge por escrito lo que se dijo en ellas.',
  body:['La <b>ponencia</b> es una exposición oral formal. Alguien presenta una tesis, una investigación o una experiencia ante un público académico: un <b>foro</b>, un congreso o una mesa de trabajo.',
   'Se prepara por escrito y tiene un <b>tiempo limitado</b> que se respeta, porque hay otros ponentes. Por eso conviene <b>ensayar</b> en voz alta y cronometrarse antes del evento.',
   'Su <b>estructura</b> es clara: saludo y presentación; <b>introducción</b> (tema y propósito); <b>desarrollo</b> (dos o tres ideas con datos y ejemplos); <b>conclusión</b>, que retoma la tesis para que el público la recuerde; y espacio para preguntas.',
   'El <b>apoyo visual</b> lleva pocas palabras, imágenes y gráficas. Se muestra, no se lee: las diapositivas llenas de párrafos compiten con tu voz.',
   'La voz y el cuerpo también comunican: <b>volumen</b>, <b>pausas</b>, <b>énfasis</b>, contacto visual y postura. Una pausa antes de una idea importante la destaca. Hablar de espaldas, hacia el tablero, rompe la conexión con el público.',
   'Mientras tanto, el <b>relator</b> escucha y toma notas de cada ponente, y anota las preguntas y los acuerdos. Luego redacta la <b>relatoría</b>: una síntesis que recoge con <b>fidelidad</b> lo que se dijo, sin cambiar las ideas aunque no esté de acuerdo.',
   'Al final de la relatoría, el relator puede agregar una breve reflexión propia, señalada como tal. Después la lee o la entrega a los participantes.'],
  bites:[{ej:'En el Foro Educativo Distrital de Bogotá, estudiantes y docentes presentan sus experiencias en ponencias breves.',check:{q:'¿Qué es una ponencia?',o:['Una exposición oral formal ante un público académico','Una charla informal en el descanso'],a:0,e:'Es formal, preparada y con una tesis o una experiencia que presentar.'}},
   {ej:'Si te dan cinco minutos, ensaya con el cronómetro del celular: si te pasas, recorta un ejemplo.',ojo:'Pasarse del tiempo, aunque el tema sea interesante, le quita el turno a los demás ponentes.'},
   {ej:'"Buenos días, soy Laura, de décimo. Hoy quiero demostrar que la biblioteca del barrio es un derecho. Primero… Segundo… Por eso… Quedo atenta a sus preguntas."',check:{q:'¿Qué hace la conclusión de una ponencia?',o:['Retoma la tesis','Presenta al ponente'],a:0,e:'La conclusión amarra todo: el público se va con la idea central clara.'}},
   {ej:'Una diapositiva con una foto de la biblioteca llena y el dato "60 niños cada sábado" dice más que un párrafo.',check:{q:'¿Cómo debe ser el apoyo visual?',o:['Pocas palabras, imágenes y gráficas','Párrafos largos para leerlos'],a:0,e:'El apoyo visual se muestra; la ponencia la dice tu voz.'}},
   {ej:'Antes de decir "la biblioteca es un derecho", haz silencio un segundo y mira a todo el auditorio: la frase pega más fuerte.',ojo:'Reparte la mirada por todo el auditorio, no solo al profe ni al tablero.',check:{q:'¿Para qué sirve una pausa antes de una idea importante?',o:['Para destacarla','Para gastar tiempo'],a:0,e:'La pausa prepara al público y le da énfasis a la idea.'}},
   {ej:'Relatoría fiel: "La ponente sostuvo que la biblioteca del barrio es un derecho y propuso ampliar su horario."',ojo:'El relator no cambia lo que dijo un ponente, aunque no esté de acuerdo.',check:{q:'¿Cómo es una buena relatoría?',o:['Fiel a lo que se dijo','Corregida con la opinión del relator'],a:0,e:'La relatoría recoge con fidelidad las ideas, las preguntas y los acuerdos.'}},
   {ej:'"Reflexión del relator: me parece que faltó hablar del presupuesto." Queda claro que es su opinión y va aparte.'}],
  key:'Ponencia: ensayada y a tiempo, con introducción, desarrollo, conclusión y preguntas, voz clara y apoyo visual. Relatoría: lo que se dijo, con fidelidad.',
  co:'En el Foro Educativo Distrital de Bogotá, estudiantes y docentes presentan sus experiencias en ponencias breves, y las relatorías de cada mesa recogen las conclusiones.',
  act:{type:'record',prompt:'Graba una ponencia de dos minutos sobre un problema de tu colegio o tu barrio. Luego escúchate y evalúate.',text:'Guía: <b>Saludo y presentación</b> (10 segundos). <b>Introducción</b>: el problema y tu tesis. <b>Desarrollo</b>: dos razones, cada una con un dato o un ejemplo. <b>Conclusión</b>: retoma la tesis y propone una acción. Cierra con: "Quedo atento a sus preguntas". Si puedes, prepara una diapositiva con una imagen o un dato.',max:120,rubric:['Volumen y dicción','Pausas y énfasis','Introducción, desarrollo y conclusión claros','Uso del apoyo visual sin leerlo']},
  quiz:[{q:'¿Qué es una relatoría?',o:['Un discurso para convencer al público','Una reseña de un libro','Un texto que recoge con fidelidad lo que se dijo en una sesión','Un poema para recitar'],a:2,e:'El relator sintetiza las ideas de los ponentes, las preguntas y los acuerdos.',lv:'L'},
   {q:'Un ponente lee diapositivas llenas de texto, de espaldas al público. ¿Qué es lo más probable?',o:['Que el público pierda el interés y la conexión','Que el público se concentre más','Que la ponencia dure menos','Que mejore su volumen'],a:0,e:'Leer de espaldas rompe el contacto visual y las diapositivas cargadas compiten con la voz.',lv:'I'},
   {q:'¿Por qué conviene cerrar la ponencia retomando la tesis?',o:['Para gastar el tiempo que sobra','Porque ayuda al público a recordar la idea central y da unidad a la exposición','Porque así no hay que responder preguntas','Porque lo exige la ley'],a:1,e:'La conclusión amarra el recorrido: el público se va con la idea principal clara.',lv:'C'}],
  tip:'Organice un miniforo: tres ponentes por mesa, un moderador que controla el tiempo y un relator que lee su relatoría al final; roten los papeles.'},
 {id:'g10u3l3',title:'Revisar y corregir',time:50,std:'Desarrollo procesos de autocontrol y corrección lingüística en mi producción de textos orales y escritos.',dba:'DBA 8 (10°): produce textos académicos con coherencia y cohesión, a partir de un plan y de procesos de revisión y reescritura.',
  body:['Revisar es releer con ojos de lector. Empieza por la <b>concordancia</b>: el verbo va en el mismo número y persona que el núcleo del sujeto, y el adjetivo, en el mismo género y número que el sustantivo. El verbo <b>haber</b> impersonal va en singular.',
   'Luego, la <b>puntuación</b>. La regla clave: nunca se pone coma entre el sujeto y el verbo, aunque el sujeto sea largo.',
   'Revisa las <b>tildes diacríticas</b>, que distinguen palabras iguales: <i>tú/tu, él/el, sé/se, sí/si, mí/mi, más/mas</i>. <i>Qué</i> lleva tilde también en preguntas indirectas. Y los monosílabos <i>fue, dio, vio, ti</i> no llevan tilde.',
   'Las <b>agudas</b> (fuerza en la última sílaba) llevan tilde si terminan en <i>n</i>, <i>s</i> o vocal. Las <b>graves</b> (penúltima), si no terminan así. Las <b>esdrújulas</b> y <b>sobresdrújulas</b> la llevan siempre.',
   'Hay casos especiales. Una <i>i</i> o una <i>u</i> con la fuerza, junto a <i>a, e, o</i>, forma un <b>hiato</b> y lleva tilde aunque rompa las reglas: <i>país, raíz, baúl, búho</i>. En cambio, <i>guion</i> y <i>truhan</i> cuentan como <b>monosílabos</b>: sin tilde.',
   'Ojo con las palabras que suenan igual. <i>Vende</i> va con v, de <i>vender</i>. <i>A ver</i> (mirar) no es <i>haber</i> (verbo). <i>Hay</i> (de haber), <i>ahí</i> (lugar) y <i>ay</i> (queja) son distintas. <i>Llame</i> (orden a usted) no es <i>llamé</i> (yo, en pasado).',
   'Por último, las <b>repeticiones</b>. Una palabra repetida se cambia por un <b>pronombre</b>, un <b>sinónimo</b> o se omite. Las palabras comodín, como <i>cosa</i> o <i>hacer</i>, se cambian por otras más exactas. Leer en voz alta ayuda a encontrar lo que el ojo no ve.'],
  bites:[{ej:'"Los resultados del examen fue publicado" → "Los resultados del examen fueron publicados". "Las calles están sucio" → "sucias". "Hubieron quejas" → "Hubo quejas".',ojo:'El núcleo del sujeto es "resultados", no "examen": no te dejes engañar por la palabra más cercana al verbo.',check:{q:'¿Cuál está bien?',o:['Hubieron muchas quejas','Hubo muchas quejas'],a:1,e:'Haber impersonal va siempre en singular: "muchas quejas" no es su sujeto.'}},
   {ej:'"Los estudiantes de décimo, ganaron la feria" → "Los estudiantes de décimo ganaron la feria".',check:{q:'¿Dónde está el error en "Mi primo de Cali, llegó ayer"?',o:['En la coma entre sujeto y verbo','En la palabra "ayer"'],a:0,e:'"Mi primo de Cali" es el sujeto: no se separa del verbo con coma.'}},
   {ej:'"Yo no sé qué pasó, pero él dice que sí." "Sé" es de saber, "qué" va en una pregunta indirecta, "él" es pronombre y "sí" afirma.',ojo:'"Fué" y "dió" con tilde son errores muy comunes: son monosílabos.',check:{q:'¿Cuál está bien escrita?',o:['El sábado fué la feria','El sábado fue la feria'],a:1,e:'"Fue" es monosílabo: no lleva tilde.'}},
   {ej:'Agudas: menú, maracuyá, Medellín, ciempiés (arroz, no: termina en z). Graves: carácter, huésped, tórax, bíceps (examen, resumen, tenemos, no). Esdrújulas: exámenes, régimen, Cúcuta. Sobresdrújula: dándoselo.',ojo:'Las graves terminadas en dos consonantes (bíceps) sí llevan tilde. Y en el plural la fuerza puede moverse: carácter → caracteres, régimen → regímenes.',check:{q:'¿Por qué "maracuyá" lleva tilde?',o:['Es aguda y termina en vocal','Es grave y termina en vocal'],a:0,e:'La fuerza cae en "yá", la última sílaba, y termina en vocal.'}},
   {ej:'raíz → raíces, oír, reír, búho, baúl, país: todas con hiato y tilde. Truhan, fue y dio: una sola sílaba, sin tilde.',check:{q:'¿Por qué "país" lleva tilde?',o:['Por el hiato: la i tiene la fuerza junto a la a','Porque es esdrújula'],a:0,e:'La tilde marca que "pa-ís" son dos sílabas.'}},
   {ej:'Aviso con errores: "Se bende lote. Aber si se anima: hay le dejo el número. Llamé ya." Correcto: "Se vende lote. A ver si se anima: ahí le dejo el número. Llame ya."',check:{q:'"___ le dejo el número" (señalando un lugar)',o:['Hay','Ahí','Ay'],a:1,e:'"Ahí" indica lugar.'}},
   {ej:'"Leyó los resultados y comentó los resultados" → "Leyó los resultados y los comentó".',ojo:'Truco: lee tu texto en voz alta. Donde te quedes sin aire, falta una pausa; donde algo suene raro, hay un error.'}],
  key:'Concordancia, puntuación, tildes (reglas generales, diacríticas e hiatos), palabras que suenan igual y repeticiones: revisa en ese orden y lee en voz alta.',
  co:'Avisos como "Se bende lote" o "Hay le dejo el número", o menús con "arróz" y "maracuya", circulan en redes: son errores reales que sirven para practicar.',
  act:{type:'choose',prompt:'Lee cada frase y elige qué hay que corregir.',items:[{s:'"Los resultados del examen fue publicado ayer."',o:['Error de concordancia','Error de tilde','Está bien'],a:0,e:'El núcleo del sujeto es "resultados" (plural): fueron publicados.'},{s:'"Los estudiantes de décimo, ganaron la feria."',o:['Falta una tilde','Sobra la coma entre sujeto y verbo','Está bien'],a:1,e:'Nunca va coma entre el sujeto y el verbo.'},{s:'"Hubieron muchas preguntas del público."',o:['Está bien','Debe ser "Hubo": haber impersonal va en singular'],a:1,e:'"Muchas preguntas" no es el sujeto: haber impersonal no concuerda con él.'},{s:'"Yo no se qué pasó."',o:['Sobra la tilde de "qué"','Falta la tilde de "sé" (de saber)','Está bien'],a:1,e:'"Sé", del verbo saber, lleva tilde diacrítica; "qué" la lleva porque es una pregunta indirecta.'},{s:'"El sábado fué la feria."',o:['"Fue" no lleva tilde: es monosílabo','Está bien'],a:0,e:'Fue, dio, vio y ti son monosílabos: van sin tilde.'},{s:'"Pedimos arroz y jugo de maracuya."',o:['Falta la tilde en "arroz"','Falta la tilde en "maracuyá"','Está bien'],a:1,e:'Maracuyá es aguda y termina en vocal; arroz es aguda pero termina en z.'},{s:'"Hay le dejo el número."',o:['Debe ser "Ahí" (lugar)','Debe ser "Ay" (queja)','Está bien'],a:0,e:'"Ahí" indica un lugar; "hay" viene de haber.'},{s:'"Leyó los resultados y comentó los resultados."',o:['Error de tilde','Repetición: mejor "y los comentó"','Está bien'],a:1,e:'El pronombre "los" evita repetir la palabra.'}],e:'Revisa en orden: concordancia, puntuación, tildes, palabras que suenan igual y repeticiones.'},
  quiz:[{q:'¿Cuál oración está bien escrita?',o:['Los resultados fue publicados.','Los resultados fueron publicados.','Los resultado fueron publicado.','Los resultados fueron publicado.'],a:1,e:'Sujeto plural ("los resultados") pide verbo y participio en plural.',lv:'L'},
   {q:'¿Por qué es incorrecto "Hubieron muchas quejas"?',o:['Porque "quejas" debe ir en singular','Porque falta una tilde en "hubieron"','Porque sobra una coma','Porque el verbo haber impersonal se usa en singular: "Hubo muchas quejas"'],a:3,e:'"Muchas quejas" es el complemento, no el sujeto: haber impersonal no concuerda con él.',lv:'I'},
   {q:'¿Por qué conviene leer el texto en voz alta antes de entregarlo?',o:['Porque así se escribe más rápido','Porque el oído detecta repeticiones, oraciones demasiado largas y pausas mal puntuadas','Porque es obligatorio','Porque así no hay que usar tildes'],a:1,e:'Al escucharlo, lo que suena raro suele ser un error de puntuación, de concordancia o de estilo.',lv:'C'}],
  tip:'Pida a los estudiantes que fotografíen un aviso con errores en su barrio; en clase, corrijan los mejores y expliquen la regla que se rompió.'}
]}
]};
export default grade;
